def operatorExceptionalFamily (h𝒜 : IsAlmostDisjoint 𝒜)
    (T : Space 𝕜 𝒜 →L[𝕜] Space 𝕜 ℬ) : Set 𝒜 :=
  ⋃ k : ℕ, {A : 𝒜 | residualCoordinate T k (familyVector 𝕜 𝒜 h𝒜 A) ≠ 0}

